def fl(p,r=3,c=FLAME): return dict(k='fl',p=p,r=r,c=c,core=CORE)
def fgl(p,c='#FFC060',a=0.1,**k): return dict(k='fgl',p=p,c=c,a=a,**k)
def sc(r,n,c='#FFFFFF'): return dict(k='sc',r=r,n=n,c=c)
def wave(r,n,c='#FFE0A0'): return dict(k='wave',r=r,n=n,c=c)
def rain(r,n,sp,slant,c,a=0.5,ln=6): return dict(k='rain',r=r,n=n,sp=sp,slant=slant,c=c,a=a,len=ln)
