def build(path='index.html'):
    src={}
    for f in sorted(glob.glob('art/plates/stage_*.png')):
        i=os.path.basename(f)[6:-4]; src[i]='data:image/png;base64,'+base64.b64encode(open(f,'rb').read()).decode()
    blk='/*STAGES:BEGIN*/\nconst STAGE_PLATE_SRC='+json.dumps(src,separators=(',',':'))+';\nconst STAGE_FX='+json.dumps(FX,separators=(',',':'))+';\n/*STAGES:END*/'
    s=open(path,encoding='utf-8').read()
    a=s.index('/*STAGES:BEGIN*/'); b=s.index('/*STAGES:END*/')+len('/*STAGES:END*/')
    open(path,'w',encoding='utf-8').write(s[:a]+blk+s[b:]); print('embedded',len(src),'plates,',len(FX),'venues with effects,',len(blk)//1024,'KB')
if __name__=='__main__': build()
